NOT g1  (.O(w1), .I(x[0]));
NOT g2  (.O(w2), .I(x[1]));
AND g3  (.O(w3), .I0(x[0]), .I1(x[1]));
AND g4  (.O(w4), .I0(x[2]), .I1(x[3]));
OR  g5  (.O(w5), .I0(w3), .I1(w4));
NOT g6  (.O(w6), .I(x[2]));
NOT g7  (.O(w7), .I(x[3]));
