// finite-state machine that implements the timer described in the problem
// description.
module TopModule(
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output reg shift_ena,
    output reg counting,
    output reg done
);
    reg [3:0] pattern;
    reg [3:0] shift_reg;
    reg [31:0] counter;
    reg counting_up;
    reg [1:0] state;
    parameter IDLE = 2'b00;
    parameter WAIT1 = 2'b01;
    parameter WAIT2 = 2'b10;
    always @(posedge clk) begin
        if (reset) begin
            shift_ena <= 1'b0;
            counting <= 1'b0;
            done <= 1'b0;
            pattern <= 4'b1101;
            shift_reg <= 4'b0000;
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (data == pattern[3]) begin
                        if (data == pattern[2] && data == pattern[1] && data == pattern[0]) begin
                            shift_ena <= 1'b1;
                            state <= WAIT1;
                        end
                    end
                end
                WAIT1: begin
                    shift_ena <= 1'b0;
                    shift_reg <= {shift_reg[2:0], data};
                    state <= WAIT2;
                end
                WAIT2: begin
                    counting <= 1'b1;
                    if (done_counting) begin
                        counting <= 1'b0;
                        done <= 1'b1;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            counter <= 32'd0;
            counting_up <= 1'b1;
        end else begin
            if (counting_up) begin
                counter <= counter + 32'd1;
                if (counter == shift_reg) begin
                    counting_up <= 1'b0;
                end
            end else begin
                if (ack) begin
                    done <= 1'b0;
                    counter <= 32'd0;
                    counting_up <= 1'b1;
                end
            end
        end
    end
endmodule

